	r1 := <-this.PrivatePostFuturesAssetIdLeverage(this.Extend(request, paramsOmitted))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Value

	ch <- AsyncResult[map[string]any]{Value: response}
