func (this *Mudrex) reduceMarginBody(ch chan AsyncResult[MarginModification], symbol string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.AddMarginAsync(symbol, OpNeg(amount), params)
	if r.Err != nil {
		panic(r.Err)
	}
	ch <- AsyncResult[MarginModification]{Value: r.Value}
	return nil
}

/**
 * @method
 * @name mudrex#fetchMyTrades
 * @description fetch all trades made by the user, derived from the TRANSACTION rows of the fee history endpoint - FUNDING rows are excluded and each fill's REBATE row is netted into the trade fee
 * @see https://docs.trade.mudrex.com/docs/fees
 * @param {string} [symbol] unified market symbol, applied client-side because the endpoint has no symbol filter
 * @param {int} [since] the earliest time in ms to fetch trades for, applied client-side
 * @param {int} [limit] the maximum number of trade structures to retrieve, further pages are requested until the limit is satisfied, the history ends or the page cap is reached
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.trade_currency] the settlement currency to filter trades by, 'USDT' (default) or 'INR'
 * @param {int} [params.paginationCalls] the maximum number of pages to request (default 10) - a symbol with few or no recent fills can exhaust the cap and return fewer than limit trades
 * @returns {Trade[]} a list of [trade structures](https://docs.ccxt.com/#/?id=trade-structure)
 */
func (this *Mudrex) FetchMyTradesAsync(optionalArgs ...any) <-chan AsyncResult[[]Trade] {
	ch := make(chan AsyncResult[[]Trade], 1)
	go this.fetchMyTradesBody(ch, optionalArgs...)
	return ch
}
func (this *Mudrex) fetchMyTradesBody(ch chan AsyncResult[[]Trade], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
	}
	maxCalls, paramsPaginationCalls := this.HandleOptionIntegerAndParams(params, "fetchMyTrades", "paginationCalls", 10)
	// every fill produces a TRANSACTION row plus a REBATE row and funding rows share the page, so over-request and paginate until the unified limit is satisfied
	var pageSize any = func() any {
		if limit == nil {
			return 0
		}
		return *limit * 2
	}()
	var allRows []any = []any{}
	var transactionsCount int64 = this.ParseToInt(0)
	var calls int64 = this.ParseToInt(0)
	var offset any = 0
	var paging bool = true
	for paging {
		var request map[string]any = map[string]any{}
		if (limit != nil) && (*limit > 0) {
			request["limit"] = pageSize
			request["offset"] = offset
		}

		r1 := <-this.PrivateGetFuturesFeeHistory(this.Extend(request, paramsPaginationCalls))
		if r1.Err != nil {
			panic(r1.Err)
		}
		var response map[string]any = r1.Value
		var data []any = SafeListTyped(response, "data")
		var dataLength int = len(data)
		for i := 0; i < len(data); i++ {
			var entry any = data[i]
			allRows = append(allRows, entry)
			if this.SafeString(entry, "fee_type") != nil && *this.SafeString(entry, "fee_type") == "TRANSACTION" {
				// count only rows the client-side symbol filter keeps, otherwise a symbol-filtered call under-returns
				if (market == nil) || (IsEqual(this.SafeString(entry, "symbol"), market["id"])) {
					transactionsCount = this.ParseToInt(transactionsCount + 1)
				}
			}
		}
		calls = this.ParseToInt(calls + 1)
		paging = false
		// the page cap bounds the walk when the requested symbol has few or no rows anywhere near the top of the history
		if (limit != nil) && (dataLength == pageSize) {
			if (transactionsCount < *limit) && (calls < maxCalls) {
				// this.sum keeps the offset numeric across the php transpile, see https://github.com/ccxt/ccxt/pull/29684
				offset = this.Sum(offset, pageSize)
				paging = true
			}
		}
	}
	// a REBATE row is a partial refund of one fill's TRANSACTION fee, matched by symbol, time and notional - each rebate is consumed once, so equal fills sharing a key net exactly one refund apiece
	var rebateKeys []any = []any{}
	var rebateAmounts []any = []any{}
	var transactions []any = []any{}
	var transactionKeys []string = []string{}
	for i := 0; i < len(allRows); i++ {
		var entry any = DerefScalar(allRows[i])
		var feeType *string = this.SafeString(entry, "fee_type")
		var pairKey string = *this.SafeString(entry, "symbol", "") + ":" + *this.SafeString(entry, "created_at", "") + ":" + *this.SafeString(entry, "transaction_amount", "")
		if feeType != nil && *feeType == "TRANSACTION" {
			transactions = append(transactions, entry)
			transactionKeys = append(transactionKeys, pairKey)
		} else if feeType != nil && *feeType == "REBATE" {
			rebateKeys = append(rebateKeys, pairKey)
			rebateAmounts = append(rebateAmounts, this.SafeString(entry, "fee_amount", "0"))
		}
	}
	var rows []any = []any{}
	for i := 0; i < len(transactions); i++ {
		var rebate *string = nil
		for j := 0; j < len(rebateKeys); j++ {
			if DerefScalar(rebateKeys[j]) == GetValue(transactionKeys, i) {
				rebate = this.SafeString(rebateAmounts, j)
				// blank the consumed key so the next equal fill matches the next rebate, never the same one twice
				AddElementToObject(rebateKeys, j, "")
				break
			}
		}
		if rebate == nil {
			rows = append(rows, DerefScalar(transactions[i]))
		} else {
			rows = append(rows, this.Extend(DerefScalar(transactions[i]), map[string]any{
				"rebate_amount": rebate,
			}))
		}
	}

	ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.ParseTrades(rows, market, since, limit))}
	return nil
}
func (this *Mudrex) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	//     {
	//         "id": "019f21e1-9093-7333-866d-31f19c1300ed",
	//         "symbol": "APTUSDT",
	//         "fee_amount": "0.02468116",
	//         "fee_perc": "0.05900003",
	//         "fee_type": "TRANSACTION",
	//         "created_at": "2026-07-02T08:10:58Z",
	//         "transaction_amount": "41.83245",
	//         "trade_currency": "USDT",
	//         "order_type": "LONG",
	//         "trigger_type": "MARKET",
	//         "gst_amount": "0.00376492"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var ms *string = this.SafeString(trade, "symbol")
	var marketResolved map[string]any = this.SafeMarket(ms, market)
	var symbol *string = SafeStringPtr(marketResolved["symbol"])
	var ts *int64 = this.Parse8601(this.SafeString(trade, "created_at"))
	// exit fills carry STOPLOSS / TAKEPROFIT markers without the closing direction, so their unified direction stays undefined
	var side *string = this.SafeStringLower(trade, "order_type")
	var tradeSide *string = nil
	if side != nil && *side == "long" {
		tradeSide = SafeStringPtr("buy")
	} else if side != nil && *side == "short" {
		tradeSide = SafeStringPtr("sell")
	}
	var trig *string = this.SafeStringUpper(trade, "trigger_type")
	var takerOrMaker *string = nil
	if trig != nil && *trig == "MARKET" {
		// a market execution always takes liquidity, a limit execution can be either
		takerOrMaker = SafeStringPtr("taker")
	}
	var fee map[string]any = nil
	var feeCostString *string = this.SafeString(trade, "fee_amount")
	// rebate_amount is attached by fetchMyTrades from the fill's REBATE row - the reported fee is the net charge
	var rebateString *string = this.SafeString(trade, "rebate_amount")
	if (feeCostString != nil) && (rebateString != nil) {
		feeCostString = Precise.StringSub(feeCostString, rebateString)
	}
	if feeCostString != nil {
		fee = map[string]any{
			"cost":     feeCostString,
			"currency": this.SafeString(trade, "trade_currency"),
		}
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"timestamp":    ts,
		"datetime":     this.Iso8601(ts),
		"symbol":       symbol,
		"id":           this.SafeString(trade, "id"),
		"order":        nil,
		"type":         this.SafeStringLower(trade, "trigger_type"),
		"side":         tradeSide,
		"takerOrMaker": takerOrMaker,
		"price":        nil,
		"amount":       nil,
		"cost":         this.SafeString(trade, "transaction_amount"),
		"fee":          fee,
	}, marketResolved)
}

/**
 * @method
 * @name mudrex#transfer
 * @description transfer currency internally between wallets on the same account
 * @see https://docs.trade.mudrex.com/docs
 * @param {string} code unified currency code
 * @param {float} amount amount to transfer
 * @param {string} fromAccount 'spot' or 'futures'
 * @param {string} toAccount 'spot' or 'futures'
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transfer structure](https://docs.ccxt.com/#/?id=transfer-structure)
 */
func (this *Mudrex) TransferAsync(code string, amount any, fromAccount string, toAccount string, optionalArgs ...any) <-chan AsyncResult[TransferEntry] {
	ch := make(chan AsyncResult[TransferEntry], 1)
	go this.transferBody(ch, code, amount, fromAccount, toAccount, optionalArgs...)
	return ch
}
func (this *Mudrex) transferBody(ch chan AsyncResult[TransferEntry], code string, amount any, fromAccount string, toAccount string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var mp map[string]any = map[string]any{
		"spot":    "SPOT",
		"SPOT":    "SPOT",
		"futures": "FUTURES",
		"future":  "FUTURES",
		"FUTURES": "FUTURES",
	}
	var fw *string = this.SafeString(mp, fromAccount, strings.ToUpper(fromAccount))
	var tw *string = this.SafeString(mp, toAccount, strings.ToUpper(toAccount))
	var body map[string]any = map[string]any{
		"from_wallet_type": fw,
		"to_wallet_type":   tw,
		"amount":           this.NumberToString(amount),
	}
	var useInr bool = false
	if code == "INR" {
		useInr = true
	} else {
		// default USDT does not use the inr path
		var tradeCurrency *string = this.SafeString2(params, "trade_currency", "tradeCurrency")
		if tradeCurrency != nil && *tradeCurrency == "INR" {
			useInr = true
		}
	}
	var response map[string]any = nil
	if useInr {

		r := <-this.PrivatePostFuturesTransfersInr(this.Extend(body, params))
		if r.Err != nil {
			panic(r.Err)
		}
		response = r.Value
	} else {

		r1 := <-this.PrivatePostWalletFuturesTransfer(this.Extend(body, params))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	}
	var data any = this.SafeDict(response, "data", response)

	ch <- AsyncResult[TransferEntry]{Value: TransferEntryFromMap(map[string]any{
		"info":        response,
		"id":          this.SafeString(data, "id"),
		"timestamp":   nil,
		"datetime":    nil,
		"currency":    code,
		"amount":      amount,
		"fromAccount": fw,
		"toAccount":   tw,
		"status":      "ok",
	})}
	return nil
}

func NewMudrex(userConfig map[string]any) *Mudrex {
	p := newMudrex()
	p.Init(userConfig)
	return p
}

func (this *Mudrex) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

